selector_to_html = {"a[href=\"#pal\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u53ef\u79fb\u690d\u62bd\u8c61\u5c42\uff08PAL\uff09<a class=\"headerlink\" href=\"#pal\" title=\"Link to this heading\">#</a></h3><p>\u901a\u8fc7\u9002\u914d\u5668\u6a21\u5f0f\u5b9e\u73b0\u786c\u4ef6\u62bd\u8c61\u3002\u6bcf\u6b21\u6784\u5efa\u9009\u62e9\u4e00\u4e2a\u8bbe\u5907\u9002\u914d\u5668\u548c\u4e24\u4e2a CCL \u9002\u914d\u5668\uff08\u4e3b\u673a + \u8bbe\u5907\uff09\uff1a</p>", "a[href=\"#crl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u901a\u4fe1\u8fd0\u884c\u65f6\u5c42\uff08CRL\uff09<a class=\"headerlink\" href=\"#crl\" title=\"Link to this heading\">#</a></h3><p>\u8fd0\u884c\u65f6\u5b9e\u73b0\u4e86\u56db\u79cd\u6267\u884c\u7b56\u7565\uff08runner\uff09\uff0c\u6839\u636e\u901a\u4fe1\u5668\u7c7b\u578b\u548c\u73af\u5883\u914d\u7f6e\u8fdb\u884c\u9009\u62e9\uff1a</p>", "a[href=\"#uil\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u63a5\u53e3\u5c42\uff08UIL\uff09<a class=\"headerlink\" href=\"#uil\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagcx/include/flagcx.h</span></code> \u4e2d\u5b9a\u4e49\u7684\u516c\u5171 C API\u3002\u5b83\u516c\u5f00\u4e86\uff1a</p>", "a[href=\"backend-support.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u540e\u7aef\u652f\u6301<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u4e0b\u8868\u603b\u7ed3\u4e86\u5f53\u524d\u652f\u6301\u7684\u901a\u4fe1\u540e\u7aef\u53ca\u5176\u5bf9\u5e94\u7684\u529f\u80fd\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u67b6\u6784<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>FlagCX \u5206\u4e3a\u4e09\u5c42\uff1a</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagCX \u662f\u4e00\u4e2a\u53ef\u6269\u5c55\u3001\u81ea\u9002\u5e94\u7684\u8de8\u82af\u7247\u901a\u4fe1\u5e93\u3002\u5b83\u4f5c\u4e3a\u4e00\u4e2a\u5e73\u53f0\uff0c\u5f00\u53d1\u8005\u3001\u7814\u7a76\u4eba\u5458\u548c AI \u5de5\u7a0b\u5e08\u53ef\u4ee5\u5728\u5404\u79cd\u9879\u76ee\u4e0a\u8fdb\u884c\u534f\u4f5c\uff0c\u4e3a\u524d\u6cbf AI \u89e3\u51b3\u65b9\u6848\u7684\u5f00\u53d1\u505a\u51fa\u8d21\u732e\uff0c\u5e76\u4e0e\u5168\u7403\u793e\u533a\u5206\u4eab\u4ed6\u4eec\u7684\u5de5\u4f5c\u3002</p><p>FlagCX \u5229\u7528\u539f\u751f\u96c6\u5408\u901a\u4fe1\u5e93\u5728\u5404\u5e73\u53f0\u4e0a\u63d0\u4f9b\u5b8c\u6574\u7684\u5355\u82af\u7247\u901a\u4fe1\u652f\u6301\u3002\u9664\u4e86\u5176\u539f\u751f x-CCL \u96c6\u6210\u5916\uff0cFlagCX \u8fd8\u5f15\u5165\u4e86\u539f\u521b\u7684\u8bbe\u5907\u7f13\u51b2\u533a IPC \u548c\u8bbe\u5907\u7f13\u51b2\u533a RDMA \u6280\u672f\uff0c\u4e3a\u8de8\u82af\u7247\u548c\u5355\u82af\u7247\u573a\u666f\u542f\u7528\u9ad8\u6027\u80fd P2P \u64cd\u4f5c\u3002\u8fd9\u4e9b\u673a\u5236\u53ef\u4ee5\u4e0e\u539f\u751f x-CCL \u540e\u7aef\u65e0\u7f1d\u7ed3\u5408\uff0c\u4e3a\u8de8\u82af\u7247\u96c6\u5408\u901a\u4fe1\u63d0\u4f9b\u4f18\u5316\u6027\u80fd\u3002</p>", "a[href=\"application-integration.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e94\u7528\u96c6\u6210<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagCX \u4e0e\u4e0a\u5c42\u5e94\u7528\u5982 <a class=\"reference external\" href=\"https://pytorch.org/\">PyTorch</a> \u548c <a class=\"reference external\" href=\"https://github.com/PaddlePaddle/\">PaddlePaddle</a> \u96c6\u6210\u3002\n\u4e0b\u8868\u5217\u51fa\u4e86 FlagCX \u652f\u6301\u7684\u6846\u67b6\u53ca\u5176\u76f8\u5173\u901a\u4fe1\u64cd\u4f5c\uff0c\u5176\u4e2d <code class=\"docutils literal notranslate\"><span class=\"pre\">batch_XXX</span></code> \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">XXX_coalesced</span></code> \u64cd\u4f5c\u6307\u7684\u662f\u4f7f\u7528\u7ec4\u539f\u8bed\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
